CREATE TABLE `com_ordenes_compra` (
  `idcompra` bigint(20) UNSIGNED NOT NULL,
  `requisicionid` int(11) NOT NULL COMMENT 'ID de la requisición que originó esta compra',
  `proveedorid` bigint(20) UNSIGNED NOT NULL COMMENT 'Proveedor seleccionado para esta OC',
  `plantaid` bigint(20) DEFAULT NULL COMMENT 'Para qué planta',
  `almacenid` bigint(20) UNSIGNED NOT NULL COMMENT 'Almacén donde se recibirá la mercancía',
  `estatus` enum('emitida','en_transito','recibida','recibida_parcial','cerrada','cancelada') DEFAULT 'emitida' COMMENT 'Estado actual de la OC',
  `moneda` varchar(3) DEFAULT 'MXN' COMMENT 'Código ISO de la moneda',
  `tipo_cambio` decimal(15,6) DEFAULT 1.000000 COMMENT 'Tipo de cambio al momento de emitir',
  `subtotal` decimal(18,6) NOT NULL DEFAULT 0.000000,
  `iva` decimal(18,6) NOT NULL DEFAULT 0.000000,
  `total` decimal(18,6) NOT NULL DEFAULT 0.000000,
  `observaciones` text DEFAULT NULL COMMENT 'Condiciones comerciales o notas para el proveedor',
  `created_by` bigint(20) UNSIGNED NOT NULL COMMENT 'Usuario que generó la OC',
  `updated_by` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Último usuario en modificarla',
  `deleted_by` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Usuario que la canceló/eliminó',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

