  `inventarioid` bigint(20) NOT NULL COMMENT 'El producto/servicio real',
  `tipo_elemento` char(1) NOT NULL DEFAULT 'P' COMMENT 'P=Producto, S=Servicio, H=Herramienta, K=Kit',
  `cantidad` decimal(12,4) NOT NULL COMMENT 'Cantidad real a comprar a este proveedor',
