  `estatus` varchar(50) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE	El distribuidor generó el pedido y todavía no ha sido tomado por Administración.\r\nEN_REVISION	Administración comenzó a validar cantidades, disponibilidad, destinos y condiciones comerciales.\r\nPARCIAL	        El pedido contiene líneas atendidas y otras pendientes o en Back Order.\r\nBACK_ORDER	Ninguna o la mayor parte de las unidades puede atenderse actualmente por falta de disponibilidad.\r\nAUTORIZADO	Las unidades fueron autorizadas/asignadas y están listas para avanzar a facturación.\r\nFACTURADO	Todas las unidades aplicables del pedido fueron facturadas.\r\nENTREGADO	Todas las unidades del pedido fueron entregadas.\r\nCANCELADO	El pedido fue cancelado antes de completar el proceso.',
  `idmotivo_cancelacion` int(11) DEFAULT NULL,
  `motivo_cancelacion_otro` varchar(500) DEFAULT NULL,
  `fecha_cancelacion` datetime DEFAULT NULL,
  `cancelado_por` int(11) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1 COMMENT 'Número de versión del pedido; inicia en 1 y aumenta por cada modificación realizada',
  `ultima_modificacion_por` int(11) DEFAULT NULL COMMENT 'ID del usuario de acceso que realizó la última modificación del pedido',
  `fecha_ultima_modificacion` datetime DEFAULT NULL COMMENT 'Fecha y hora de la última modificación realizada al pedido',
  `estado` tinyint(1) NOT NULL DEFAULT 1 COMMENT '2=Activo 1 inactivo 0 Eliminado',
  `fecha_creacion` datetime NOT NULL,
  `fecha_actualizacion` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Volcado de datos para la tabla `ped_pedidos`
