  `impuesto4` double DEFAULT NULL COMMENT 'Impuesto\r\n4\r\n',
  `imp4_aplica` int(11) DEFAULT NULL COMMENT 'Impuesto 4 aplica a {0,1,3,4} .: 0= Exento, 1 = Precio Base , 2 =Acumulado 1, 2= Acumulado 3, 4=Acumulado 3',
  `impuesto5` double DEFAULT NULL COMMENT 'Impuesto 5',
  `imp5_aplica` int(11) DEFAULT NULL COMMENT 'Impuesto 5 aplica a {0,1,2,3,4,6,7} .: 0=Precio Base, 1 = Acumulado1, 2 = Acumulado2, 3 = Acumulado3, 4 = Exento, 6 = No aplica, 7 = Acumulado4',
  `impuesto6` double DEFAULT NULL COMMENT 'Impuesto 6\r\n',
  `imp6_aplica` int(11) DEFAULT NULL COMMENT 'Impuesto 6 aplica a {0,1,2,3,4,6,7,8} .: 0=Precio Base, 1 = Acumulado1, 2 = Acumulado2, 3 = Acumulado3, 4 = Exento, 6 = No aplica, 7 = Acumulado4, 8 = Acumulado5',
  `impuesto7` double DEFAULT NULL COMMENT 'Impuesto 7',
  `imp7_aplica` int(11) DEFAULT NULL COMMENT 'Impuesto 7 aplica a {0,1,2,3,4,6,7,8,9} .: 0=Precio Base, 1 = Acumulado1, 2 = Acumulado2, 3 = Acumulado3, 4 = Exento, 6 = No aplica, 7 = Acumulado4, 8 = Acumulado5, 9 = Acumulado6',
  `impuesto8` double DEFAULT NULL COMMENT 'Impuesto 8',
  `imp8_aplica` int(11) DEFAULT NULL COMMENT 'Impuesto 8 aplica a {0,1,2,3,4,6,7,8,9,10} .: 0=Precio Base, 1 = Acumulado1, 2 = Acumulado2, 3 = Acumulado3, 4 = Exento, 6 = No aplica, 7 = Acumulado4, 8 = Acumulado5, 9 = Acumulado6, 10 = Acumulado7',
  `fecha_creacion` datetime DEFAULT NULL,
  `estado` varchar(1) DEFAULT '2' COMMENT '0=Eliminada 1=inactiva 2=Activa'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

