DROP TABLE IF EXISTS `w_ot_kpi_base`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u546825723_mrpuser`@`127.0.0.1` SQL SECURITY DEFINER VIEW `w_ot_kpi_base`  AS SELECT `ot`.`idorden` AS `idorden`, `ot`.`num_sub_orden` AS `num_sub_orden`, `pe`.`planeacionid` AS `planeacionid`, `p`.`num_orden` AS `num_orden`, `p`.`productoid` AS `productoid`, `p`.`supervisorid` AS `supervisorid`, `p`.`prioridad` AS `prioridad`, `p`.`cantidad` AS `cantidad_planeada`, `p`.`fecha_requerida` AS `fecha_requerida`, `p`.`fecha_inicio` AS `fecha_inicio_planeada`, `p`.`fecha_fin` AS `fecha_fin_planeada`, `pe`.`estacionid` AS `estacionid`, `e`.`cve_estacion` AS `cve_estacion`, `e`.`nombre_estacion` AS `nombre_estacion`, `e`.`proceso` AS `proceso`, `pe`.`orden` AS `orden_estacion`, `enc`.`usuarioid` AS `encargado_id`, concat(`uenc`.`nombres`,' ',`uenc`.`apellidos`) AS `encargado_nombre`, `ayu`.`usuarioid` AS `ayudante_id`, concat(`uayu`.`nombres`,' ',`uayu`.`apellidos`) AS `ayudante_nombre`, cast(nullif(`e`.`estandar`,'') as decimal(12,2)) AS `estandar_min`, nullif(`ot`.`fecha_inicio`,'0000-00-00 00:00:00') AS `fecha_inicio_real`, nullif(`ot`.`fecha_fin`,'0000-00-00 00:00:00') AS `fecha_fin_real`, CASE WHEN nullif(`ot`.`fecha_inicio`,'0000-00-00 00:00:00') is not null AND nullif(`ot`.`fecha_fin`,'0000-00-00 00:00:00') is not null THEN timestampdiff(SECOND,nullif(`ot`.`fecha_inicio`,'0000-00-00 00:00:00'),nullif(`ot`.`fecha_fin`,'0000-00-00 00:00:00')) / 60.0 ELSE NULL END AS `duracion_real_min`, `ot`.`estatus` AS `estatus`, `ot`.`calidad` AS `calidad`, CASE WHEN nullif(`ot`.`fecha_fin`,'0000-00-00 00:00:00') is not null THEN 1 ELSE 0 END AS `cerrada`, CASE WHEN cast(nullif(`e`.`estandar`,'') as decimal(12,2)) is not null AND cast(nullif(`e`.`estandar`,'') as decimal(12,2)) > 0 AND nullif(`ot`.`fecha_inicio`,'0000-00-00 00:00:00') is not null AND nullif(`ot`.`fecha_fin`,'0000-00-00 00:00:00') is not null AND timestampdiff(SECOND,nullif(`ot`.`fecha_inicio`,'0000-00-00 00:00:00'),nullif(`ot`.`fecha_fin`,'0000-00-00 00:00:00')) / 60.0 <= cast(nullif(`e`.`estandar`,'') as decimal(12,2)) THEN 1 ELSE 0 END AS `en_tiempo`, CASE WHEN cast(nullif(`e`.`estandar`,'') as decimal(12,2)) is not null AND cast(nullif(`e`.`estandar`,'') as decimal(12,2)) > 0 AND nullif(`ot`.`fecha_inicio`,'0000-00-00 00:00:00') is not null AND nullif(`ot`.`fecha_fin`,'0000-00-00 00:00:00') is not null AND timestampdiff(SECOND,nullif(`ot`.`fecha_inicio`,'0000-00-00 00:00:00'),nullif(`ot`.`fecha_fin`,'0000-00-00 00:00:00')) / 60.0 > 0 THEN cast(nullif(`e`.`estandar`,'') as decimal(12,2)) / (timestampdiff(SECOND,nullif(`ot`.`fecha_inicio`,'0000-00-00 00:00:00'),nullif(`ot`.`fecha_fin`,'0000-00-00 00:00:00')) / 60.0) * 100 ELSE NULL END AS `eficiencia_pct_base` FROM (((((((`mrp_ordenes_trabajo` `ot` join `mrp_planeacion_estacion` `pe` on(`pe`.`id_planeacion_estacion` = `ot`.`planeacion_estacionid`)) join `mrp_planeacion` `p` on(`p`.`idplaneacion` = `pe`.`planeacionid`)) join `mrp_estacion` `e` on(`e`.`idestacion` = `pe`.`estacionid`)) left join `mrp_planeacion_estacion_operador` `enc` on(`enc`.`planeacion_estacionid` = `pe`.`id_planeacion_estacion` and `enc`.`rol` = 'ENCARGADO' and `enc`.`estado` = 2)) left join `usuarios` `uenc` on(`uenc`.`idusuario` = `enc`.`usuarioid`)) left join `mrp_planeacion_estacion_operador` `ayu` on(`ayu`.`planeacion_estacionid` = `pe`.`id_planeacion_estacion` and `ayu`.`rol` = 'AYUDANTE' and `ayu`.`estado` = 2)) left join `usuarios` `uayu` on(`uayu`.`idusuario` = `ayu`.`usuarioid`)) ;

